CREATE FUNCTION public.admin_summary() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; BEGIN PERFORM public.require_primary_administrator(false); SELECT jsonb_build_object('pendingApplications',(SELECT count(*) FROM public.admin_applications WHERE status IN ('Pending','Information requested')),'totalApplications',(SELECT count(*) FROM public.admin_applications),'totalTransactions',(SELECT count(*) FROM public.admin_transactions),'registrations',(SELECT jsonb_agg(jsonb_build_object('month',to_char(m,'Mon'),'count',(SELECT count(*) FROM public.admin_customers c WHERE c.created_at>=m AND c.created_at<m+interval '1 month'))) FROM generate_series(date_trunc('month',now())-interval '5 months',date_trunc('month',now()),interval '1 month') m)) INTO result; RETURN result; END; $$;
REVOKE ALL ON FUNCTION public.admin_summary() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.admin_summary() TO authenticated;